  function primeFactorCount(n){
    n=Math.abs(Math.trunc(n));
    if(n<2)return 0;
    let count=0,x=n;
    for(let p=2;p*p<=x;p+=(p===2?1:2)){
      while(x%p===0){count++;x/=p;}
    }
    if(x>1)count++;
    return count;
  }
